#!/bin/bash
# Common variables and custom helpers shared by all app scripts.

OPENCODE_INSTALL_URL="https://opencode.ai/v2/install"

# Absolute path of the OpenCode binary installed by the official installer.
opencode_bin_path() {
    printf '%s/.opencode/bin/opencode' "$data_dir"
}

# Dedicated config file passed to OpenCode with OPENCODE_CONFIG, so the package
# does not overwrite an admin-owned opencode.json / opencode.jsonc. This file
# holds every provider generated by the package (local Ollama and, optionally,
# one external provider).
opencode_config_dir() {
    printf '%s/.config/opencode' "$data_dir"
}

opencode_ynh_config_path() {
    printf '%s/ynh-ollama.json' "$(opencode_config_dir)"
}

# Human-readable label for the selected external provider.
external_provider_label() {
    case "${1:-none}" in
        openai) printf 'OpenAI' ;;
        anthropic) printf 'Anthropic' ;;
        mistral) printf 'Mistral' ;;
        *) printf 'None' ;;
    esac
}

# OpenCode's web UI requests its assets, API and service worker from the
# origin root (/_assets/..., /api/..., /sw.js). A YunoHost subpath therefore
# cannot work: those root requests miss the app location and are caught by
# SSOwat instead of OpenCode. Web instances must be installed at "/".
validate_web_path() {
    local value="${1:-${path:-/}}"

    [ "$value" = "/" ] || ynh_die \
        "OpenCode web mode requires the path '/' because the web UI serves its assets, API and service worker from the domain root. Use '/' on this domain, or install the web instance on a dedicated domain."
}

# Compute the Basic auth header nginx injects into proxied requests. This lets
# the web UI talk to its own local server without an interactive pairing link:
# YunoHost SSO remains the only login the browser sees.
prepare_opencode_web_auth() {
    local password="${service_password:-}"

    if [ -z "$password" ]; then
        password=$(opencode_cli service get password 2>/dev/null || true)
    fi
    if [ -z "$password" ]; then
        password=$(ynh_app_setting_get --key=service_password 2>/dev/null || true)
    fi
    [ -n "$password" ] || ynh_die "The OpenCode service password is missing; cannot configure web authentication."

    service_password="$password"
    opencode_basic_auth=$(printf 'opencode:%s' "$password" | base64 -w0)
}

# Print the app id of an installed YunoHost Ollama app, if any.
find_installed_ollama_app() {
    local apps_json
    apps_json=$(yunohost app list --output-as json 2>/dev/null || true)
    printf '%s' "$apps_json" | python3 -c '
import json, re, sys
try:
    data = json.load(sys.stdin)
except Exception:
    sys.exit(0)
for item in data.get("apps", []):
    app_id = str(item.get("id", ""))
    if re.fullmatch(r"ollama(__[0-9]+)?", app_id):
        print(app_id)
        break
'
}

# Generate the package-managed OpenCode config. It always includes the detected
# local Ollama provider and, when selected, one external provider with its API
# key. Settings are refreshed here so install, upgrade and config panel stay
# in sync.
configure_opencode_providers() {
    ynh_script_progression "Configuring OpenCode providers..."

    local arg_provider="${1:-}" arg_api_key="${2:-}"
    local config_dir config_file ollama_app ollama_port base_url
    local external_provider external_api_key

    config_dir=$(opencode_config_dir)
    config_file=$(opencode_ynh_config_path)
    mkdir -p "$config_dir"

    external_provider="$arg_provider"
    [ -n "$external_provider" ] || external_provider=$(ynh_app_setting_get --key=external_provider 2>/dev/null || true)
    [ -n "$external_provider" ] || external_provider="none"

    external_api_key="$arg_api_key"
    [ -n "$external_api_key" ] || external_api_key=$(ynh_app_setting_get --key=external_api_key 2>/dev/null || true)

    case "$external_provider" in
        none|openai|anthropic|mistral) ;;
        *) ynh_die "Unsupported external provider: $external_provider" ;;
    esac

    if [ "$external_provider" = "none" ]; then
        external_api_key=""
    elif [ -z "$external_api_key" ]; then
        ynh_die "An API key is required for $(external_provider_label "$external_provider")."
    fi

    ollama_app=$(find_installed_ollama_app || true)
    base_url=""
    if [ -n "$ollama_app" ]; then
        ollama_port=$(ynh_app_setting_get --app="$ollama_app" --key=port 2>/dev/null || true)
        [[ "$ollama_port" =~ ^[0-9]+$ ]] || ollama_port=11434
        base_url="http://127.0.0.1:${ollama_port}/v1"
    fi

    EXTERNAL_PROVIDER="$external_provider" \
    EXTERNAL_API_KEY="$external_api_key" \
    OLLAMA_BASE_URL="$base_url" \
    python3 - "$config_file" <<'PY'
import json, os, sys

path = sys.argv[1]
providers = {}

base_url = os.environ.get("OLLAMA_BASE_URL", "")
if base_url:
    providers["ollama"] = {
        "name": "Ollama (local)",
        "settings": {"baseURL": base_url},
    }

provider = os.environ.get("EXTERNAL_PROVIDER", "none")
api_key = os.environ.get("EXTERNAL_API_KEY", "")
if provider in ("openai", "anthropic", "mistral") and api_key:
    providers[provider] = {"settings": {"apiKey": api_key}}

config = {"$schema": "https://opencode.ai/config.json"}
if providers:
    config["providers"] = providers

with open(path, "w") as f:
    json.dump(config, f, indent=2)
    f.write("\n")
PY

    ynh_app_setting_set --key=external_provider --value="$external_provider"
    ynh_app_setting_set --key=external_api_key --value="$external_api_key"
    ynh_app_setting_set --key=ollama_app --value="$ollama_app"
    ynh_app_setting_set --key=ollama_base_url --value="$base_url"

    chown "$app:$app" "$config_file"
    chmod 600 "$config_file"

    if [ -n "$ollama_app" ]; then
        ynh_print_info "OpenCode will use local Ollama ($ollama_app) at $base_url."
    else
        ynh_print_info "No YunoHost Ollama app detected."
    fi
    if [ "$external_provider" = "none" ]; then
        ynh_print_info "No external provider is configured."
    else
        ynh_print_info "OpenCode will also use external provider $(external_provider_label "$external_provider")."
    fi
}

# Backward-compatible name used by older package revisions.
configure_ollama_provider() {
    configure_opencode_providers "$@"
}

# Reject wildcard or malformed addresses in VPN mode.
validate_vpn_bind_address() {
    local value="${1:-}"
    [ -z "$value" ] && return 0

    if [ "$value" = "0.0.0.0" ] || [ "$value" = "::" ]; then
        ynh_die "The VPN bind address must not be a wildcard address (0.0.0.0 or ::)."
    fi

    if [[ "$value" =~ ^([0-9]{1,3}\.){3}[0-9]{1,3}$ ]]; then
        local a b c d octet
        IFS=. read -r a b c d <<< "$value"
        for octet in "$a" "$b" "$c" "$d"; do
            [[ "$octet" =~ ^[0-9]+$ ]] && [ "$octet" -le 255 ] || \
                ynh_die "Invalid VPN bind address: $value"
        done
        return 0
    fi

    if [[ "$value" =~ ^[A-Za-z0-9]([A-Za-z0-9._-]*[A-Za-z0-9])?$ ]]; then
        return 0
    fi

    ynh_die "Invalid VPN bind address: $value (expected an IPv4 address or hostname)."
}

# Run the OpenCode CLI as the app user, with all XDG state rooted in $data_dir.
opencode_cli() {
    ynh_exec_as_app env \
        HOME="$data_dir" \
        XDG_CONFIG_HOME="$data_dir/.config" \
        XDG_DATA_HOME="$data_dir/.local/share" \
        XDG_STATE_HOME="$data_dir/.local/state" \
        XDG_CACHE_HOME="$data_dir/.cache" \
        PATH="$data_dir/.opencode/bin:$PATH" \
        "$(opencode_bin_path)" "$@"
}

# Download the current OpenCode V2 release with the official installer.
# The installer resolves the latest version from opencode.ai and handles
# x86_64/arm64, glibc/musl and baseline CPU variants.
install_opencode_binary() {
    ynh_script_progression "Downloading and installing the latest OpenCode release..."

    mkdir -p "$data_dir/.opencode/bin"
    chown -R "$app:$app" "$data_dir"

    ynh_exec_as_app env \
        HOME="$data_dir" \
        XDG_CONFIG_HOME="$data_dir/.config" \
        XDG_DATA_HOME="$data_dir/.local/share" \
        XDG_STATE_HOME="$data_dir/.local/state" \
        XDG_CACHE_HOME="$data_dir/.cache" \
        SHELL=/bin/bash \
        bash -c 'curl -fsSL "$0" | bash -s -- --no-modify-path' "$OPENCODE_INSTALL_URL"

    local version
    version=$(opencode_cli --version 2>/dev/null | awk '{print $NF}' | sed 's/^v//')
    [ -n "$version" ] || ynh_die "OpenCode was installed but its version could not be read."

    ynh_app_setting_set --key=opencode_version --value="$version"
}

# Apply hostname/port/password to OpenCode's own service configuration.
set_opencode_service_binding() {
    local bind="$1"
    local password="$2"

    service_password="$password"
    bind_address="$bind"

    opencode_cli service set hostname "$bind"
    opencode_cli service set port "$port"
    opencode_cli service set password "$password"
}

# Enable the encrypted OpenTunnel and remember its stable address.
# With required=1 a failure is returned to the caller so it can restore the
# previous service state before aborting.
enable_remote_tunnel() {
    local required="${1:-0}"
    local pair_file pair_url

    ynh_script_progression "Enabling the encrypted OpenTunnel proxy (this can take a minute)..."
    pair_file=$(mktemp)
    if opencode_cli pair --remote --yes >"$pair_file" 2>&1; then
        remote_enabled=1
        ynh_app_setting_set --key=remote_enabled --value=1
        # Keep the stable tunnel address, not the one-time pairing link.
        pair_url=$(grep -oE 'https://[^[:space:]]+/auth/connect/' "$pair_file" | head -1 | sed 's#/auth/connect/$##' || true)
        if [ -n "$pair_url" ]; then
            remote_url="$pair_url"
            ynh_app_setting_set --key=remote_url --value="$remote_url"
        fi
    else
        cat "$pair_file" >&2
        rm -f "$pair_file"
        remote_enabled=0
        ynh_app_setting_set --key=remote_enabled --value=0
        if [ "$required" = "1" ]; then
            return 1
        fi
        ynh_print_warn "OpenTunnel could not be enabled during install. You can enable it later from the YunoHost config panel."
        return 0
    fi
    rm -f "$pair_file"
}

disable_remote_tunnel() {
    opencode_cli service set remote false >/dev/null 2>&1 || true
    remote_enabled=0
    remote_url=""
    ynh_app_setting_set --key=remote_enabled --value=0
    ynh_app_setting_set --key=remote_url --value=""
}

# Persist the server settings in OpenCode's own service configuration and,
# when requested, enable the OpenTunnel proxy.
configure_opencode_service() {
    ynh_script_progression "Configuring the OpenCode service..."

    local password bind
    password=$(ynh_string_random --length=48)
    bind="127.0.0.1"

    if [ "${exposure:-}" = "vpn" ] && [ -n "${vpn_bind_address:-}" ]; then
        validate_vpn_bind_address "$vpn_bind_address"
        bind="$vpn_bind_address"
    fi

    ynh_app_setting_set --key=service_password --value="$password"
    ynh_app_setting_set --key=bind_address --value="$bind"
    ynh_app_setting_set --key=remote_url --value=""
    ynh_app_setting_set --key=remote_enabled --value=0

    # Custom settings are only reloaded as bash variables on the next script
    # run, so publish the values needed by helpers called later here too.
    set_opencode_service_binding "$bind" "$password"
    remote_url=""
    remote_enabled=0

    if [ "${exposure:-}" = "proxy" ]; then
        enable_remote_tunnel 0
    else
        disable_remote_tunnel
    fi

    # The CLI may have started a service while applying settings. Stop it so
    # that systemd becomes the single owner of the server process.
    opencode_cli service stop >/dev/null 2>&1 || true
}

# Change the exposure after install without rotating the service password.
# Used by the YunoHost config panel action.
apply_remote_access_mode() {
    local new_exposure="${1:-${exposure:-}}"
    local new_domain="${2:-${domain:-}}"
    local new_path="${3:-${path:-}}"
    local new_group="${4:-${web_access_group:-}}"
    local new_vpn_bind="${5:-${vpn_bind_address:-}}"

    local old_domain old_path old_group old_vpn_bind
    old_domain=$(ynh_app_setting_get --key=domain 2>/dev/null || true)
    old_path=$(ynh_app_setting_get --key=path 2>/dev/null || true)
    old_group=$(ynh_app_setting_get --key=web_access_group 2>/dev/null || true)
    old_vpn_bind=$(ynh_app_setting_get --key=vpn_bind_address 2>/dev/null || true)

    [ -n "$new_exposure" ] || new_exposure=$(ynh_app_setting_get --key=exposure 2>/dev/null || true)
    [ -n "$new_exposure" ] || new_exposure=web
    case "$new_exposure" in
        web|proxy|vpn) ;;
        *) ynh_die "Unknown exposure mode: $new_exposure" ;;
    esac

    [ -n "$new_domain" ] || new_domain="$old_domain"
    [ -n "$new_path" ] || new_path="${old_path:-/}"
    [ -n "$new_group" ] || new_group="${old_group:-all_users}"
    [ -n "$new_vpn_bind" ] || new_vpn_bind="$old_vpn_bind"
    [[ "$new_path" == /* ]] || new_path="/$new_path"

    if [ "$new_exposure" = "web" ]; then
        [ -n "$new_domain" ] || ynh_die "A YunoHost domain is required in web mode."
        validate_web_path "$new_path"
    fi

    local bind="127.0.0.1"
    if [ "$new_exposure" = "vpn" ]; then
        validate_vpn_bind_address "$new_vpn_bind"
        bind="${new_vpn_bind:-127.0.0.1}"
    fi

    local password
    password=$(ynh_app_setting_get --key=service_password 2>/dev/null || true)
    [ -n "$password" ] || ynh_die "The OpenCode service password is missing from app settings."
    port="${port:-$(ynh_app_setting_get --key=port 2>/dev/null || true)}"
    [ -n "$port" ] || ynh_die "The OpenCode port is missing from app settings."

    ynh_script_progression "Switching OpenCode to the $new_exposure exposure..."
    ynh_systemctl --service="$app" --action="stop" || true

    set_opencode_service_binding "$bind" "$password"
    if [ "$new_exposure" = "proxy" ]; then
        if ! enable_remote_tunnel 1; then
            # Keep the previous systemd configuration running on failure.
            disable_remote_tunnel
            opencode_cli service stop >/dev/null 2>&1 || true
            ynh_systemctl --service="$app" --action="start" || true
            ynh_die "OpenTunnel could not be enabled. Check the logs and try again from the config panel."
        fi
    else
        disable_remote_tunnel
    fi

    # The CLI may have started a service while applying settings. Stop it so
    # that systemd becomes the single owner of the server process.
    opencode_cli service stop >/dev/null 2>&1 || true

    ynh_app_setting_set --key=exposure --value="$new_exposure"
    ynh_app_setting_set --key=domain --value="$new_domain"
    ynh_app_setting_set --key=path --value="$new_path"
    ynh_app_setting_set --key=web_access_group --value="$new_group"
    ynh_app_setting_set --key=vpn_bind_address --value="$new_vpn_bind"
    ynh_app_setting_set --key=bind_address --value="$bind"

    exposure="$new_exposure"
    domain="$new_domain"
    path="$new_path"
    web_access_group="$new_group"
    vpn_bind_address="$new_vpn_bind"
    bind_address="$bind"

    install_system_unit

    if [ "$new_exposure" = "web" ] && [ -n "$old_domain" ] && [ "$old_domain" != "$new_domain" ]; then
        # Drop the nginx config from the previous domain before creating the new one.
        local previous_domain="${domain:-}"
        domain="$old_domain"
        ynh_config_remove_nginx
        domain="$previous_domain"
    fi

    if [ "$new_exposure" = "web" ]; then
        prepare_opencode_web_auth
        ynh_config_add_nginx
        if ynh_permission_exists --permission=main; then
            ynh_permission_delete --permission=main
        fi
        ynh_permission_create --permission=main --url="$new_path" --allowed="$new_group" --auth_header=false
    else
        ynh_config_remove_nginx
        if ynh_permission_exists --permission=main; then
            ynh_permission_delete --permission=main
        fi
    fi

    ynh_systemctl --service="$app" --action="start"
    register_remote_url

    ynh_print_info "OpenCode is now reachable using the $new_exposure exposure."
}

install_system_unit() {
    ynh_script_progression "Installing the OpenCode systemd unit..."

    mkdir -p "/var/log/$app"
    chown "$app:$app" "/var/log/$app"
    ynh_config_add_systemd
}

register_yunohost_service() {
    yunohost service add "$app" \
        --description="OpenCode AI coding agent" \
        --log="/var/log/$app/$app.log"
}

wait_for_opencode_api() {
    local url="http://${bind_address:-127.0.0.1}:${port}/api/info"
    local i

    for i in $(seq 1 30); do
        if curl -fsS -u "opencode:${service_password}" "$url" >/dev/null 2>&1; then
            return 0
        fi
        sleep 2
    done

    return 1
}

# Store the public OpenTunnel URL so the admin can find it after install.
register_remote_url() {
    [ "${exposure:-}" = "proxy" ] || return 0
    [ "${remote_enabled:-0}" = "1" ] || return 0

    service_password=${service_password:-$(ynh_app_setting_get --key=service_password)}
    bind_address=${bind_address:-$(ynh_app_setting_get --key=bind_address)}
    remote_url=${remote_url:-$(ynh_app_setting_get --key=remote_url)}

    ynh_script_progression "Retrieving the OpenTunnel address..."

    if ! wait_for_opencode_api; then
        [ -n "${remote_url:-}" ] || ynh_print_warn "OpenCode API did not become ready in time; the proxy URL could not be recorded."
        return 0
    fi

    local info remote
    info=$(curl -fsS -u "opencode:${service_password}" \
        "http://${bind_address:-127.0.0.1}:${port}/api/info" 2>/dev/null || true)

    remote=$(printf '%s' "$info" | python3 -c '
import json, sys
try:
    data = json.load(sys.stdin)
except Exception:
    sys.exit(0)
for url in data.get("urls", []):
    if "opentunnel" in url:
        print(url)
        break
' 2>/dev/null || true)

    if [ -n "$remote" ]; then
        remote_url="$remote"
        ynh_app_setting_set --key=remote_url --value="$remote"
    elif [ -z "${remote_url:-}" ]; then
        ynh_print_warn "Could not read the OpenTunnel URL from /api/info. Pair again with: opencode pair --remote --yes"
    fi
}
